package pt.ulusofona.cd.supplier.model;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="supplier") public class Supplier implements Identifiable { @Id @Column(nullable=false,updatable=false) private UUID id; @Column(nullable=false,length=150) private String name; @Column(nullable=false,length=254) private String email; @Column(length=30) private String phone; @Column(length=300) private String address; @Column(nullable=false) private boolean active; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt; @Version @Column(nullable=false) private long version; protected Supplier(){} public Supplier(UUID id,String name,String email,String phone,String address,boolean active){this.id=id;this.name=name;this.email=email;this.phone=phone;this.address=address;this.active=active;} @PrePersist void create(){Instant n=Instant.now();if(id==null)id=UUID.randomUUID();createdAt=n;updatedAt=n;} @PreUpdate void update(){updatedAt=Instant.now();} public UUID getId(){return id;} public String getName(){return name;} public void setName(String v){name=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public String getAddress(){return address;} public void setAddress(String v){address=v;} public boolean isActive(){return active;} public void setActive(boolean v){active=v;} public Instant getCreatedAt(){return createdAt;} public Instant getUpdatedAt(){return updatedAt;} public long getVersion(){return version;} }
